import{DAY_MS,CHECK_PHASES,taskKey,expected,newPractice,practiceTarget,practiceStep,newPilot,beginCheck,checkStep,pilotSummary,pilotCSV}from'./growth.js';
const growthRoot=document.querySelector('#app');
const gEsc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const gRead=k=>{try{return JSON.parse(window.fixiverseStorage.getItem(k)||'null');}catch{return null;}};
const pilotKey=m=>`fixiverse-checkins-${m}-v1`,practiceKey=m=>`fixiverse-practice-${m}-v1`,visitsKey=m=>`fixiverse-practice-visits-${m}-v1`;
const missionName=m=>m==='fraction'?'Fraction Foundry':'Pattern Grove';
const helpName=h=>({independent:'no tutor help',tutor:'tutor help recorded',unknown:'tutor help unknown'})[h]||'help not recorded';
const phaseName=p=>({before:'Before learning',after:'After learning',later:'Next-day check'})[p];
let gMission='fraction',gPractice=null,gPilot=null,gChoice=null,gError='',gMode='practice',gKeep=false;
const gButton=(text,action,attrs='')=>`<button class="btn" data-growth="${action}" ${attrs}>${text}</button>`;
const dateLabel=n=>new Date(n).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
function gHeader(){return`<header><div class="brand">fixiverse <span class="growth-bookmark">LITTLE STEPS</span></div><div class="header-actions">${gButton('Tutor workspace','tutor')}${gButton('My bookshelf','home')}${gButton('Read aloud','read')}</div></header>`;}
function gLayout(title,body){const previousY=window.scrollY;const prefs=gRead('fixiverse-access-v1')||{};document.title=`Fixiverse · ${title}`;growthRoot.className=`hub storybook-mission growth-screen ${prefs.large?'large':''} ${prefs.motion?'reduced':''}`;growthRoot.innerHTML=`${gHeader()}<main id="main" class="growth-shell"><div class="eyebrow">${missionName(gMission)} / YOUR NEXT LITTLE STEP</div><h1 id="screen-title" tabindex="-1">${title}</h1>${gError?`<p class="result soft" role="status">${gEsc(gError)}</p>`:''}${body}<p class="growth-local">${window.fixiverseStorage.memoryOnly?'Storage unavailable. This visit will be lost on reload.':'Saved only for this learner in this browser.'} Read-aloud and help stay available.</p></main>`;growthRoot.dataset.growthMode=gMode;if(gKeep){window.scrollTo(0,previousY);gKeep=false;}else{document.querySelector('#screen-title').focus({preventScroll:true});window.scrollTo(0,0);}}
function gTask(t,help=false){if(t.kind==='fraction')return`<div class="growth-bars">${t.pair.map((n,i)=>`<div class="growth-bar-line"><span class="fraction" aria-label="one over ${n}"><em>1</em><i>${n}</i></span><div><span class="growth-bar-label">${i?'RIGHT':'LEFT'} WHOLE · ONE PIECE</span><div class="fraction-bar" role="img" aria-label="${i?'Right':'Left'} matching whole split into ${n} equal parts, one shaded">${Array.from({length:n},(_,j)=>`<i class="part ${j?'':'selected'}"></i>`).join('')}</div></div></div>`).join('')}<p class="hint-text">Same-sized wholes. Equal parts. Compare one shaded piece.</p></div>`;
const icons={sun:'☀',leaf:'❧',star:'★',moon:'☾'},tile=(x,i)=>`<span class="grove-tile ${x} ${i<t.block.length?'loop-tile':''}" role="img" aria-label="${x}">${icons[x]}</span>`;return`<div class="growth-loop"><span class="eyebrow">THE LITTLE LOOP</span><div>${t.block.map(tile).join('')}</div><p>Follow this loop along the path.</p><div class="pattern-path">${Array.from({length:t.length},(_,i)=>tile(t.block[i%t.block.length],i)).join('')}<span class="grove-tile mystery" role="img" aria-label="Missing next tile">?</span></div></div>`;}
function gChoices(t,selected=null){const values=t.kind==='fraction'?[['left','Left piece'],['equal','Same size'],['right','Right piece']]:[['sun','Sun'],['leaf','Leaf'],['star','Star'],['moon','Moon']];return`<div class="growth-choices" role="group" aria-label="${t.kind==='fraction'?'Which piece is bigger?':'What comes next?'}">${values.map(([v,label])=>`<button class="choice ${selected===v?'selected':''}" data-growth="choose" data-value="${v}" aria-pressed="${selected===v}">${label}</button>`).join('')}</div>`;}
function savePractice(next){window.fixiverseStorage.setItem(practiceKey(gMission),JSON.stringify(next));if(next.complete){const history=gRead(visitsKey(gMission))||[],record={id:next.id,at:Date.now(),target:next.target.title,answers:next.answers,hints:next.hints};window.fixiverseStorage.setItem(visitsKey(gMission),JSON.stringify([record,...history.filter(v=>v.id!==record.id)].slice(0,40)));}gPractice=next;}
function startPractice(m,source=null){gChoice=null;gMission=m;gError='';const p=gRead(pilotKey(m))||newPilot(m);window.fixiverseStorage.setItem(pilotKey(m),JSON.stringify(p));const old=gRead(practiceKey(m));if(old&&!old.complete){gPractice=old;renderPractice();return;}const target=(source==='mentor'?window.fixiverseMentor?.practiceTarget(m):null)||practiceTarget(gRead('fixiverse-foundry-v1'),gRead('fixiverse-pattern-v1'),m),reserved=Object.values(p.plan).flat().map(taskKey),history=gRead(visitsKey(m))||[];const next=newPractice(m,target,reserved,history.length*3);next.id=crypto.randomUUID();savePractice(next);renderPractice();}
function renderPractice(){gMode='practice';const s=gPractice;if(s.complete){gLayout('One more little breakthrough.',`<section class="panel"><div class="panel-body"><h2>${gEsc(s.target.title)}</h2><p>${s.answers.filter(a=>a.firstTry).length} of 3 fit on the first try. ${s.answers.filter(a=>a.revealed).length} needed a worked answer. Hints used: ${s.hints}.</p><p>Practice is for trying things. This is a record of this visit, not a mastery score.</p><div class="btn-row">${gButton('Back to tutor notes','tutor')}${gButton('A learning check-in','pilot',`data-mission="${gMission}"`)}${gButton('Another short practice','practice',`data-mission="${gMission}"`)}</div></div></section>`);return;}const t=s.tasks[s.index];gLayout(s.target.title,`<p class="lede">${gEsc(s.target.why)} Three small questions, with help when you need it.</p><div class="growth-layout"><section class="panel"><div class="panel-head"><span>Practice ${s.index+1} of 3</span><span class="label">YOUR PACE</span></div><div class="panel-body">${gTask(t)}<h2>${t.kind==='fraction'?'Which piece is bigger?':'What comes next?'}</h2>${s.tested?'':gChoices(t,s.choice)}${s.feedback?`<p class="result ${s.revealed?'soft':''}" role="status">${gEsc(s.feedback)}</p>`:''}<div class="btn-row">${s.tested?gButton(s.index===2?'Keep my practice':'Next little question','practice-next'):gButton('Try my idea','practice-submit',s.choice?'':'disabled')}${gButton('A little hint','practice-hint')}</div></div></section><aside class="grove-companion"><div class="eyebrow">PIP’S PRACTICE NOTE</div><h2>You can try again.</h2><p>${s.index===0?'Start by looking carefully. You don’t have to be sure.':s.answers.at(-1)?.firstTry?'Your last idea fit on the first try. Try this one before taking a hint.':'A little support helped us look closer. It stays available for the next question.'}</p><p>No points to lose. If a rule still feels mixed up after two tries, we’ll look at a worked answer together.</p>${gButton('Read this page','read')}</aside></div>`);}
function pilotSection(){return`<section class="tutor-section growth-pilot-section"><div class="section-heading"><h2>Learning check-ins</h2><span>Only real, recorded responses appear here</span></div><p class="growth-note">Optional before, after, and next-day questions for a small tutoring pilot. Different questions are reserved across the three check-ins and kept out of targeted practice. Regular mission items may overlap. This is not a validated assessment.</p><div class="signal-grid">${['fraction','pattern'].map(m=>{const p=gRead(pilotKey(m)),rows=pilotSummary(p);return`<article class="signal-card"><h3>${missionName(m)}</h3><div class="growth-mini-results">${rows.map(r=>`<div><span>${phaseName(r.phase)}</span><b>${r.recorded?`${r.correct}/${r.total}`:'Not recorded'}</b></div>`).join('')}</div><details class="growth-history"><summary>Recorded targeted practice</summary>${(gRead(visitsKey(m))||[]).length?`<ul>${(gRead(visitsKey(m))||[]).slice(0,3).map(v=>`<li>${gEsc(v.target)} · ${v.answers.filter(a=>a.firstTry).length}/3 first try · ${v.answers.filter(a=>a.revealed).length} worked answers · ${v.hints} hints</li>`).join('')}</ul>`:'<p>No finished practice visits recorded.</p>'}</details>${gButton(p?.current?'Resume check-in':'Open check-ins','pilot',`data-mission="${m}"`)}</article>`;}).join('')}</div><div class="btn-row">${gButton('Download check-in CSV · all learners','export')}</div><p class="growth-note">Scores describe these tasks only. Help, timing, and readiness self-reports are exported alongside answers. A small convenience pilot cannot establish effectiveness.</p></section>`;}
function showPilot(m){gChoice=null;gMission=m;gError='';gPilot=gRead(pilotKey(m))||newPilot(m);if(gPilot.current){renderCheck();return;}const rows=pilotSummary(gPilot);gLayout('A little learning check-in.',`<p class="lede">Three questions each time. Asking for help is always allowed and recorded.</p><section class="panel"><div class="panel-body"><h2>For your learner and tutor, together.</h2><p>Use “before” ahead of learning, “after” when you finish, and the next-day check at least 24 hours later. These use different questions of the same broad types. They are not a clinical or standardized test.</p><div class="growth-check-stages">${rows.map((r,i)=>{const ready=i===0||rows[i-1].recorded,unlock=gPilot.checks.after?.completedAt+DAY_MS,delayed=r.phase==='later'&&(!unlock||Date.now()<unlock);return`<article><span class="eyebrow">0${i+1}</span><h3>${phaseName(r.phase)}</h3>${r.recorded?`<p><b>${r.correct} of ${r.total}</b> responses fit.</p><p>${r.hints} hints · ${gEsc(helpName(r.adultHelp))} · readiness: ${gEsc(r.readiness)}.</p><small>${dateLabel(r.completedAt)}</small><p class="growth-note">${gPilot.checks[r.phase].context?.priorExposure?'App use was recorded before this check-in.':gPilot.checks[r.phase].context?'No earlier recorded app use at check-in start.':'Earlier app use was not recorded for this check-in.'}</p>`:`<p>${r.phase==='later'&&unlock?`Opens ${dateLabel(unlock)}.`:'No responses recorded.'}</p>${gButton('Start '+phaseName(r.phase).toLowerCase(),'begin',`data-phase="${r.phase}" ${!ready||delayed?'disabled':''}`)}`}</article>`;}).join('')}</div><div class="btn-row">${gButton('Back to tutor notes','tutor')}${gButton('Go to the mission','mission')}${gButton('Targeted practice','practice',`data-mission="${m}"`)}</div><p class="growth-note">Readiness is an optional learner self-report, not a measured confidence outcome. The next-day wait uses this device’s clock.</p></div></section>`);}
function renderCheck(){gMode='check';const c=gPilot.current;if(!c){showPilot(gMission);return;}if(c.readiness===null){gLayout('How does this feel today?',`<section class="panel"><div class="panel-body"><div class="eyebrow">${phaseName(c.phase)}</div><h2>How ready do you feel to try a new ${gMission==='fraction'?'fraction':'pattern'} question?</h2><p>Any answer is welcome. You can skip this.</p><div class="growth-readiness">${[['ready','Ready to try'],['unsure','A little unsure'],['help','I’d like some help'],['skip','Skip this question']].map(([v,label])=>gButton(label,'readiness',`data-value="${v}"`)).join('')}</div></div></section>`);return;}
if(c.index>=3){gLayout('Who helped along the way?',`<section class="panel"><div class="panel-body"><h2>For the tutor to record.</h2><p>Read-aloud and text size are access tools. Record tutoring help separately; app hints are already counted.</p><div class="growth-readiness">${[['independent','No tutor help'],['tutor','Tutor helped'],['unknown','Help not known']].map(([v,label])=>gButton(label,'finish',`data-value="${v}"`)).join('')}</div><p class="growth-note">Your responses are saved. Finishing records this check-in once.</p></div></section>`);return;}
const t=c.tasks[c.index];gLayout(`${phaseName(c.phase)} · ${c.index+1} of 3`,`<p class="lede">Take your time. Choose an idea, then keep it. We’ll show the results when this check-in is finished.</p><section class="panel"><div class="panel-body">${gTask(t)}<h2>${t.kind==='fraction'?'Which piece is bigger?':'What comes next?'}</h2>${gChoices(t,gChoice)}${c.hints?`<p class="result">${t.kind==='fraction'?'More equal parts makes each piece smaller. Matching part counts make matching pieces.':'Follow the whole little loop. After its last tile, start at the first tile again.'}</p>`:''}<div class="btn-row">${gButton('Keep my answer','answer',`data-index="${c.index}" ${gChoice?'':'disabled'}`)}${gButton('I’d like a hint','check-hint')}${gButton('Read aloud','read')}</div><p class="growth-note">You may leave and resume this check-in. Earlier answers stay recorded.</p></div></section>`);}
function checkContext(){const mission=gRead(gMission==='fraction'?'fixiverse-foundry-v1':'fixiverse-pattern-v1');const count=(gRead(visitsKey(gMission))||[]).length;const started=gRead(practiceKey(gMission));return{priorPracticeVisits:count,missionPhase:mission?.phase||'not started',priorExposure:!!(mission||started||count)};}
function exportPilot(){const report=pilotCSV(window.fixiverseProfiles.list(),(id,key)=>window.fixiverseProfiles.read(id,key));const url=URL.createObjectURL(new Blob([report.csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='fixiverse-recorded-checkins.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#announcement').textContent=report.rowCount>0?'Recorded check-in responses downloaded.':'CSV contains column headings only. No completed check-ins have been recorded.';}
document.addEventListener('click',e=>{const b=e.target.closest('[data-growth]');if(!b)return;const a=b.dataset.growth;gError='';try{if(a==='home'){window.fixiverseHome();return;}if(a==='tutor'){location.hash='tutor';window.fixiverseTutor.show();return;}if(a==='mission'){window.fixiverseLaunch(gMission);return;}if(a==='export'){exportPilot();return;}if(a==='read'){if('speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(document.querySelector('main').innerText));}else document.querySelector('#announcement').textContent='Read-aloud is not available on this device.';return;}if(a==='practice'){startPractice(b.dataset.mission,b.dataset.practiceSource);return;}if(a==='pilot'){showPilot(b.dataset.mission);return;}if(a==='choose'){gKeep=true;gChoice=b.dataset.value;if(growthRoot.dataset.growthMode==='check'){renderCheck();}else{savePractice(practiceStep(gPractice,{type:'choose',value:b.dataset.value}));renderPractice();}document.querySelector(`[data-growth="choose"][data-value="${b.dataset.value}"]`)?.focus({preventScroll:true});return;}
if(a.startsWith('practice-')){gKeep=a==='practice-hint'||a==='practice-submit';const type={ 'practice-submit':'submit','practice-next':'next','practice-hint':'hint'}[a];savePractice(practiceStep(gPractice,{type}));renderPractice();document.querySelector(`[data-growth="${gPractice.tested?'practice-next':a}"]`)?.focus({preventScroll:true});document.querySelector('#announcement').textContent=gPractice.feedback;return;}
let next;if(a==='begin')next=beginCheck(gPilot,b.dataset.phase,Date.now(),checkContext());else if(a==='readiness')next=checkStep(gPilot,{type:'readiness',value:b.dataset.value});else if(a==='answer')next=checkStep(gPilot,{type:'answer',index:+b.dataset.index,value:gChoice});else if(a==='check-hint'){gKeep=true;next=checkStep(gPilot,{type:'hint'});}else if(a==='finish')next=checkStep(gPilot,{type:'finish',value:b.dataset.value});else return;window.fixiverseStorage.setItem(pilotKey(gMission),JSON.stringify(next));gPilot=next;gChoice=null;renderCheck();if(a==='check-hint')document.querySelector('[data-growth="check-hint"]')?.focus({preventScroll:true});}catch(err){gError=err.message;document.querySelector('#announcement').textContent=gError;const main=document.querySelector('main');if(main){const old=main.querySelector('.growth-error');old?.remove();main.insertAdjacentHTML('afterbegin',`<p class="result soft growth-error" role="status">${gEsc(gError)}</p>`);}}});
window.fixiverseGrowth={practice:startPractice,pilot:showPilot,section:pilotSection};
